```tsx
import { useId } from "react";
import "./ChecklistItem.css";

export interface ChecklistItemProps {
  title: string;
  detail: string;
  minutes: number;
  done: boolean;
  onToggle: () => void;
}

export function ChecklistItem({
  title,
  detail,
  minutes,
  done,
  onToggle,
}: ChecklistItemProps) {
  const titleId = useId();
  const detailId = useId();

  return (
    <div className="checklist-item" data-done={done ? "true" : "false"}>
      <button
        type="button"
        className="checklist-item__check"
        aria-pressed={done}
        aria-labelledby={titleId}
        aria-describedby={detail ? detailId : undefined}
        onClick={onToggle}
      />
      <div className="checklist-item__text">
        <span id={titleId} className="checklist-item__title">
          {title}
        </span>
        {detail && (
          <span id={detailId} className="checklist-item__detail">
            {detail}
          </span>
        )}
      </div>
      <time className="checklist-item__duration" dateTime={`PT${minutes}M`}>
        {minutes} min
      </time>
    </div>
  );
}
```

