}

[data-theme="night"] .checklist-item {
  --myelin-surface: #15171c;
  --myelin-line: #2a2d35;
  --myelin-ink: #e8e9ed;
  --myelin-ink-muted: #a3a8b5;
  --myelin-ink-faint: #8b909c;
