  --myelin-on-accent: #0d1420;
  --myelin-focus: #9dbcff;
}

.checklist-item__check {
  appearance: none;
  flex-shrink: 0;
  position: relative;
  width: 26px;
  height: 26px;
  margin: 0;
  padding: 0;
  border-radius: 50%;
  border: 2px solid var(--myelin-ink-muted);
  background: transparent;
  cursor: pointer;
}

.checklist-item__check::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 8px;
  width: 6px;
  height: 11px;
  border: solid var(--myelin-on-accent);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg) scale(0);
}

.checklist-item__check[aria-pressed="true"] {
  background: var(--myelin-accent);
  border-color: var(--myelin-accent);
}

.checklist-item__check[aria-pressed="true"]::after {
  transform: rotate(45deg) scale(1);
}

.checklist-item__check:focus-visible {
  outline: 2px solid var(--myelin-focus);
  outline-offset: 3px;
}

.checklist-item__text {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.checklist-item__title {
  font-size: 1rem;
  line-height: 1.35;
  color: var(--myelin-ink);
  overflow-wrap: anywhere;
}

.checklist-item__detail {
  font-size: 0.875rem;
  line-height: 1.4;
  color: var(--myelin-ink-faint);
  overflow-wrap: anywhere;
}

.checklist-item__duration {
  flex-shrink: 0;
  font-size: 0.875rem;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: var(--myelin-ink-faint);
}

.checklist-item[data-done="true"] .checklist-item__title {
  color: var(--myelin-ink-muted);
}

.checklist-item[data-done="true"] .checklist-item__detail,
.checklist-item[data-done="true"] .checklist-item__duration {
  opacity: 0.7;
}

@media (prefers-reduced-motion: no-preference) {
  .checklist-item__check,
  .checklist-item__check::after {
    transition:
      background-color 150ms ease,
      border-color 150ms ease,
      transform 150ms ease;
  }
}
